class TagSet
{
    protected array $tags = [];

    public function add(string $tag): void
    {
        $this->tags[$tag] = true;
    }

    public function addAll(array $tags): void
    {
        foreach ($tags as $tag) {
            $this->add($tag);
        }
    }
}

class CountingTagSet extends TagSet
{
    public int $added = 0;

    public function add(string $tag): void
    {
        $this->added++;
        parent::add($tag);
    }

    public function addAll(array $tags): void
    {
        $this->added += count($tags);
        parent::addAll($tags);
    }
}

