namespace App\Domain\Order;

use Illuminate\Support\Facades\Auth;

final class Order
{
    private ?int $cancelledBy = null;
    private ?\DateTimeImmutable $cancelledAt = null;

    public function __construct(private OrderStatus $status) {}

    public function cancel(): void
    {
        if ($this->status === OrderStatus::Shipped) {
            throw new \DomainException('Shipped orders cannot be cancelled');
        }

        $this->status = OrderStatus::Cancelled;
        $this->cancelledBy = Auth::id();
        $this->cancelledAt = new \DateTimeImmutable();
    }
}

interface Notifier
{
    public function send(string $text): string;
}

final class SmsNotifier implements Notifier
{
    public function send(string $text): string
    {
        return "sms:$text";
    }
}

final class LoggingNotifier implements Notifier
{
    public function __construct(private Notifier $inner) {}

    public function send(string $text): string
    {
        return 'log(' . $this->inner->send($text) . ')';
    }
}

final class RetryNotifier implements Notifier
{
    public function __construct(private Notifier $inner) {}

    public function send(string $text): string
    {
        return 'retry(' . $this->inner->send($text) . ')';
    }
}

$notifier = new RetryNotifier(new LoggingNotifier(new SmsNotifier()));
echo $notifier->send('hi');
